def transform(grid):
    # Each hollow box is a container; one irregular colored pattern is propagated into containers.
    # Use the pattern-bearing object's full bounding-box mask; resize by nearest neighbor.
    a=[r[:] for r in grid]; R=len(a); C=len(a[0])
    from collections import defaultdict
    boxes=[]
    for color in range(1,10):
      ps=[(i,j) for i in range(R) for j in range(C) if a[i][j]==color]
      if not ps: continue
      r0=min(i for i,j in ps);r1=max(i for i,j in ps);c0=min(j for i,j in ps);c1=max(j for i,j in ps)
      if all(a[r0][j]==color and a[r1][j]==color for j in range(c0,c1+1)) and all(a[i][c0]==color and a[i][c1]==color for i in range(r0,r1+1)):
        if len(ps)==2*(r1-r0+1)+2*(c1-c0+1)-4: boxes.append((r0,r1,c0,c1,color))
    # Find irregular interior pattern within an otherwise solid frame of a color.
    # Pattern cells are the nonzero cells inside a box with broken interior; choose densest such box.
    candidates=[]
    for r0,r1,c0,c1,col in boxes:
      cells=[(i,j) for i in range(r0+1,r1) for j in range(c0+1,c1) if a[i][j]!=0]
      if cells: candidates.append((len(cells),r0,r1,c0,c1,col,cells))
    if not candidates:return a
    _,pr0,pr1,pc0,pc1,pcol,cells=max(candidates)
    mask={(i-pr0-1,j-pc0-1) for i,j in cells}
    sh,sw=pr1-pr0-1,pc1-pc0-1
    # Apply source pattern to other empty frames, nearest-neighbor scale.
    for r0,r1,c0,c1,col in boxes:
      if (r0,r1,c0,c1)==(pr0,pr1,pc0,pc1): continue
      h,w=r1-r0-1,c1-c0-1
      for i in range(h):
        for j in range(w):
          si=min(sh-1,round(i*(sh-1)/max(1,h-1))); sj=min(sw-1,round(j*(sw-1)/max(1,w-1)))
          a[r0+1+i][c0+1+j]=pcol if (si,sj) in mask else 0
    return a
